INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u2-C1','math',6,2,'u2',2,'보는 방향에 따라 다르게 보이는 모양 — 같은 물건도 서 있는 자리에 따라 보이는 부분과 왼쪽·오른쪽 차례가 달라지고, 여러 방향에서 본 모습을 모으면 전체 모양을 알 수 있음을 알기',ARRAY['6수03-10']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u2-C2','math',6,2,'u2',3,'위·앞·옆에서 본 모양 그리기 — 앞·뒤, 왼쪽·오른쪽은 뒤집으면 같아 세 방향이면 충분함을 알고, 위에서 본 모양에 앞 표시를 하며 앞·옆에서 본 모양은 줄마다 가장 높은 층을 그리기(옆은 앞줄이 가장 왼쪽)',ARRAY['6수03-10']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u2-C3','math',6,2,'u2',4,'쌓은 모양과 위에서 본 모양으로 개수 구하기 — 겨냥도만으로는 가려진 자리 때문에 개수가 정해지지 않을 수 있고, 위에서 본 모양으로 1층 자리를 확정한 뒤 자리마다 높이를 세어 더하기',ARRAY['6수03-09']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u2-C4','math',6,2,'u2',5,'위에서 본 모양에 수 쓰기 — 각 자리에 쌓인 쌓기나무의 개수를 쓰고 쓴 수를 모두 더해 전체 개수를 구하며, 쌓지 않은 자리는 빈 칸으로 두기',ARRAY['6수03-09']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u2-C5','math',6,2,'u2',6,'층별로 나타낸 그림으로 개수 구하기 — 층마다 위에서 본 모양을 따로 그려 개수를 더하고, 1층 모양이 위에서 본 모양과 같으며 위층 칸은 1층 자리 안에 있음을 알기',ARRAY['6수03-09']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u2-C6','math',6,2,'u2',7,'위·앞·옆에서 본 모양으로 쌓은 모양 알기 — 위에서 본 모양으로 1층을 깔고 앞·옆에서 본 모양(줄마다 가장 높은 층)으로 더 쌓을 자리를 정한 뒤 다시 세 판을 만들어 확인하기',ARRAY['6수03-10']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u2-C7','math',6,2,'u2',8,'수 쓴 그림·층별 그림으로 쌓은 모양 알기와 네 가지 표현 — 자리마다 높이가 적힌 표현(수 쓰기·층별)은 모양이 하나로 정해지고, 위·앞·옆은 가장 높은 층만 알려 주어 정해지지 않을 수 있음을 알기',ARRAY['6수03-10']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u2-C8','math',6,2,'u2',9,'여러 가지 모양 만들기 — 쌓기나무 3개로 2가지, 4개로 8가지 모양을 만들고 돌리거나 뒤집어 겹쳐지는 모양은 하나로 세며, 두 모양을 합쳐 새 모양을 만들고 되돌려 확인하기',ARRAY['6수03-10']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-2-u2-C9','math',6,2,'u2',10,'부족한 조건 찾아 쌓기 — 세 판으로 정해지는 자리부터 정하고 정해지지 않는 자리의 경우를 모두 찾은 뒤, 전체 개수 같은 조건을 더해 모양을 하나로 좁히기',ARRAY['6수03-10']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u2-X01','math',6,'u2',ARRAY['M6-2-u2-C1','M6-2-u2-C3','M6-2-u2-C6']::text[],'겨냥도에서 보이는 쌓기나무만 센다 — 앞 기둥에 가려진 자리를 빠뜨린다','위에서 본 모양으로 자리를 먼저 잡기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u2-X02','math',6,'u2',ARRAY['M6-2-u2-C3','M6-2-u2-C4','M6-2-u2-C5','M6-2-u2-C6']::text[],'위에서 본 모양(1층)의 칸 수를 전체 개수로 본다 — 높이를 세지 않는다','자리마다 몇 층인지 세어 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u2-X03','math',6,'u2',ARRAY['M6-2-u2-C1','M6-2-u2-C2','M6-2-u2-C3','M6-2-u2-C4','M6-2-u2-C5','M6-2-u2-C6','M6-2-u2-C7','M6-2-u2-C8','M6-2-u2-C9']::text[],'세기 실수 — 한두 개를 더 세거나 덜 세고, 칸 수를 잘못 더한다','자리 하나하나 짚으며 세기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u2-X04','math',6,'u2',ARRAY['M6-2-u2-C2','M6-2-u2-C6','M6-2-u2-C7']::text[],'앞에서 본 모양과 옆에서 본 모양을 바꾸어 본다','앞은 왼쪽→오른쪽 줄, 옆은 앞줄→뒷줄') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u2-X05','math',6,'u2',ARRAY['M6-2-u2-C1','M6-2-u2-C2']::text[],'옆에서 본 모양의 줄 차례를 거꾸로 한다 — 앞줄을 오른쪽에 그린다','오른쪽 옆에서는 앞줄이 가장 왼쪽') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u2-X06','math',6,'u2',ARRAY['M6-2-u2-C2','M6-2-u2-C6','M6-2-u2-C7']::text[],'앞·옆에서 본 모양에 줄의 가장 높은 층이 아니라 맨 앞 자리의 높이나 그 줄의 개수 합을 그린다','줄마다 가장 높은 층만 보여요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u2-X07','math',6,'u2',ARRAY['M6-2-u2-C2']::text[],'위에서 본 모양의 앞 표시를 빠뜨리거나 좌우·앞뒤를 뒤집어 그린다','위에서 본 모양에는 앞 표시, 앞줄이 아래') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u2-X08','math',6,'u2',ARRAY['M6-2-u2-C4','M6-2-u2-C5']::text[],'수를 쓴 그림·층별 그림에서 가장 큰 수나 층 수를 전체 개수로 읽는다','쓴 수는 모두 더하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u2-X09','math',6,'u2',ARRAY['M6-2-u2-C5','M6-2-u2-C7']::text[],'1층 모양이 위에서 본 모양과 같음을 모르거나, 위층 칸을 1층 자리 밖에 그린다','1층 = 위에서 본 모양, 위층은 1층 안에') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u2-X10','math',6,'u2',ARRAY['M6-2-u2-C6','M6-2-u2-C9']::text[],'위·앞·옆 세 판이면 쌓은 모양이 늘 하나로 정해진다고 여긴다','앞·옆은 가장 높은 층만 알려 줘요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u2-X11','math',6,'u2',ARRAY['M6-2-u2-C7']::text[],'수를 쓴 그림이나 층별 그림도 모양이 하나로 정해지지 않는다고 여긴다','자리마다 높이가 적히면 하나로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u2-X12','math',6,'u2',ARRAY['M6-2-u2-C4','M6-2-u2-C7']::text[],'k층에 쌓기나무가 있는 자리를 쓴 수가 꼭 k인 자리로만 본다(k 이상이어야 한다)','2층은 2 이상이 쓰인 자리 모두') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u2-X13','math',6,'u2',ARRAY['M6-2-u2-C8']::text[],'돌리거나 뒤집어 겹쳐지는 모양을 다른 모양으로 센다','겹쳐지면 하나로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u2-X14','math',6,'u2',ARRAY['M6-2-u2-C8']::text[],'합친 모양이나 정육면체 모양의 개수를 더하기로 세거나 한 모서리의 수로 본다','층마다 세어 더하기, 정육면체는 가로×세로×높이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u2-X15','math',6,'u2',ARRAY['M6-2-u2-C1']::text[],'같은 물건도 보는 자리에 따라 다르게 보임을 모르고, 사진 한 장으로 전체 모양을 안다고 여긴다','가려진 부분은 다른 방향에서') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u2-X16','math',6,'u2',ARRAY['M6-2-u2-C9']::text[],'세 판으로 정해지지 않는 자리에 아무 수나 넣거나, 가장 적을 때와 많을 때를 바꾸어 본다','정해지는 자리부터, 남은 자리는 경우를 모두') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u2-X17','math',6,'u2',ARRAY['M6-2-u2-C2']::text[],'앞과 뒤(왼쪽과 오른쪽)에서 본 모양이 뒤집으면 같음을 모르거나 좌우가 뒤집힌 모양을 앞에서 본 모양으로 고른다','앞·뒤는 뒤집으면 같은 모양') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u2-X18','math',6,'u2',ARRAY['M6-2-u2-C1','M6-2-u2-C2','M6-2-u2-C3','M6-2-u2-C4','M6-2-u2-C5','M6-2-u2-C6','M6-2-u2-C7','M6-2-u2-C8','M6-2-u2-C9']::text[],'묻는 말을 거꾸로 읽는다 — 옳은↔잘못된, 많을↔적을, 개수↔자리 수','물음의 「잘못·가장·몇 자리」에 동그라미 치기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u2-X19','math',6,'u2',ARRAY['M6-2-u2-C1','M6-2-u2-C2']::text[],'보는 방향의 기준을 앞에서 보는 사람으로 잡지 않는다 — 오른쪽·왼쪽·뒤를 자기가 선 자리나 그림의 위아래로 정해 「옆(오른쪽)에서 본 모양」을 왼쪽에서 본 모양으로 그리거나 사진 찍은 방향을 바꾸어 고른다','앞에서 보는 사람을 기준으로 그 사람의 오른쪽에 가서 본 것이 오른쪽(옆)에서 본 모양') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u2-X20','math',6,'u2',ARRAY['M6-2-u2-C3','M6-2-u2-C4']::text[],'위에서 본 모양(1층 자리)만 알면 자리마다 쌓인 쌓기나무 개수도 늘 정해진다고 여긴다 — 겨냥도에서 가려진 자리의 높이나 칸만 그린 위에서 본 모양으로 개수를 단정한다','위에서 본 모양은 자리를, 수를 쓴 그림은 자리마다 개수를 알려 줘요 — 높이는 쌓은 모양이나 수로 확인') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-2-u2-X21','math',6,'u2',ARRAY['M6-2-u2-C8']::text[],'돌리거나 뒤집으면 쌓기나무가 바닥에서 뜨니 그런 모양은 만들 수 없다거나 다른 모양이라고 여긴다 — 모양을 돌리거나 뒤집을 때는 쌓기나무가 서로 붙어 있다고 보아야 함을 모른다','돌리거나 뒤집어 볼 때는 쌓기나무가 붙어 있는 한 덩어리로 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u2_L02_basic#1','math',6,2,'u2','L02','tb_g6_2_math_u2_L02_basic','lesson_basic','M6-2-u2-C1',1,'mc','auto','달곰이가 가져온 과자 상자는 육각기둥 모양이에요. 이 과자 상자를 위에서 보면 어떤 모양으로 보이나요?',ARRAY['M6-2-u2-X15']::text[],true,'{"seq":1,"concept":"M6-2-u2-C1","difficulty":1,"kind":"mc","stem":"달곰이가 가져온 과자 상자는 육각기둥 모양이에요. 이 과자 상자를 위에서 보면 어떤 모양으로 보이나요?","options":[{"t":"육각형","correct":true},{"t":"직사각형","mis":"M6-2-u2-X15"},{"t":"삼각형","mis":"M6-2-u2-X15"},{"t":"원","mis":"M6-2-u2-X15"}],"explanation":["위에서 내려다보면 과자 상자의 밑면 모양이 보여요.","육각기둥의 밑면은 육각형이에요.","그래서 위에서 보면 육각형 모양으로 보여요."],"variant_rule":{"alt":[{"stem":"달곰이가 가져온 과자 상자는 육각기둥 모양이에요. 이 과자 상자를 옆에서 보면 어떤 모양으로 보이나요?","options":[{"t":"직사각형","correct":true},{"t":"육각형","mis":"M6-2-u2-X15"},{"t":"삼각형","mis":"M6-2-u2-X15"},{"t":"원","mis":"M6-2-u2-X15"}],"explanation":["옆에서 보면 과자 상자의 옆면이 보여요.","육각기둥의 옆면은 직사각형이에요.","같은 상자도 위에서는 육각형, 옆에서는 직사각형으로 보여요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u2_L02_basic#2','math',6,2,'u2','L02','tb_g6_2_math_u2_L02_basic','lesson_basic','M6-2-u2-C1',1,'mc','auto','뒷동산에서 달곰이는 바위가 판다를 닮았다고 했고, 바위 뒤에 있던 순달이는 그냥 둥근 모양이라고 했어요. 같은 바위가 다르게 보인 까닭은 무엇인가요?',ARRAY['M6-2-u2-X15']::text[],false,'{"seq":2,"concept":"M6-2-u2-C1","difficulty":1,"kind":"mc","stem":"뒷동산에서 달곰이는 바위가 판다를 닮았다고 했고, 바위 뒤에 있던 순달이는 그냥 둥근 모양이라고 했어요. 같은 바위가 다르게 보인 까닭은 무엇인가요?","options":[{"t":"서 있는 자리(보는 방향)가 달라 보이는 부분이 달라서","correct":true},{"t":"바위가 돌아갔기 때문에","mis":"M6-2-u2-X15"},{"t":"바위의 크기가 달라져서","mis":"M6-2-u2-X15"},{"t":"한 사람이 잘못 보았기 때문에","mis":"M6-2-u2-X15"}],"explanation":["바위는 그대로인데 달곰이와 순달이가 서 있는 자리가 달라요.","보는 방향이 다르면 보이는 부분과 보이지 않는 부분이 달라져요.","그래서 같은 바위도 판다 모양, 둥근 모양으로 다르게 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u2_L02_basic#3','math',6,2,'u2','L02','tb_g6_2_math_u2_L02_basic','lesson_basic','M6-2-u2-C1',1,'mc','auto','해태 조각상을 가, 나, 다, 라 네 방향에서 사진으로 찍었어요. 사진에 해태 얼굴의 정면(앞모습)이 보인다면 어느 방향에서 찍은 사진인가요?',ARRAY['M6-2-u2-X15','M6-2-u2-X19']::text[],true,'{"seq":3,"concept":"M6-2-u2-C1","difficulty":1,"kind":"mc","stem":"해태 조각상을 가, 나, 다, 라 네 방향에서 사진으로 찍었어요. 사진에 해태 얼굴의 정면(앞모습)이 보인다면 어느 방향에서 찍은 사진인가요?","options":[{"t":"가 방향","correct":true},{"t":"나 방향","mis":"M6-2-u2-X15"},{"t":"다 방향","mis":"M6-2-u2-X19"},{"t":"라 방향","mis":"M6-2-u2-X19"}],"explanation":["사진에 보이는 부분이 찍은 방향을 알려 줘요.","해태 얼굴의 정면(앞모습)이 보이려면 가 방향에서 찍어야 해요.","같은 조각상도 찍은 방향에 따라 보이는 부분이 달라요."],"variant_rule":{"alt":[{"stem":"해태 조각상을 가, 나, 다, 라 네 방향에서 사진으로 찍었어요. 사진에 해태의 뒷모습이 보인다면 어느 방향에서 찍은 사진인가요?","options":[{"t":"다 방향","correct":true},{"t":"가 방향","mis":"M6-2-u2-X15"},{"t":"나 방향","mis":"M6-2-u2-X19"},{"t":"라 방향","mis":"M6-2-u2-X19"}],"explanation":["사진에 보이는 부분이 찍은 방향을 알려 줘요.","해태의 뒷모습이 보이려면 다 방향에서 찍어야 해요.","같은 조각상도 찍은 방향에 따라 보이는 부분이 달라요."]},{"stem":"해태 조각상을 가, 나, 다, 라 네 방향에서 사진으로 찍었어요. 사진에 해태가 오른쪽 발을 공에 올려놓은 옆모습이 보인다면 어느 방향에서 찍은 사진인가요?","options":[{"t":"라 방향","correct":true},{"t":"가 방향","mis":"M6-2-u2-X15"},{"t":"나 방향","mis":"M6-2-u2-X19"},{"t":"다 방향","mis":"M6-2-u2-X19"}],"explanation":["사진에 보이는 부분이 찍은 방향을 알려 줘요.","해태가 오른쪽 발을 공에 올려놓은 옆모습이 보이려면 라 방향에서 찍어야 해요.","같은 조각상도 찍은 방향에 따라 보이는 부분이 달라요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u2_L02_basic#4','math',6,2,'u2','L02','tb_g6_2_math_u2_L02_basic','lesson_basic','M6-2-u2-C1',1,'mc','auto','4학년 1학기에 배운 평면도형의 이동을 떠올려 봐요. 도형을 왼쪽으로 뒤집으면 어떻게 되나요?',ARRAY['M6-2-u2-X17']::text[],false,'{"seq":4,"concept":"M6-2-u2-C1","difficulty":1,"kind":"mc","stem":"4학년 1학기에 배운 평면도형의 이동을 떠올려 봐요. 도형을 왼쪽으로 뒤집으면 어떻게 되나요?","options":[{"t":"도형의 왼쪽과 오른쪽이 서로 바뀐다","correct":true},{"t":"도형의 위쪽과 아래쪽이 서로 바뀐다","mis":"M6-2-u2-X17"},{"t":"도형이 시계 방향으로 돌아간다","mis":"M6-2-u2-X17"},{"t":"도형의 모양이 그대로이다","mis":"M6-2-u2-X17"}],"explanation":["도형을 왼쪽이나 오른쪽으로 뒤집으면 왼쪽과 오른쪽이 서로 바뀌어요.","위쪽이나 아래쪽으로 뒤집으면 위쪽과 아래쪽이 바뀌어요.","이 단원에서는 앞에서 본 모양과 뒤에서 본 모양이 이렇게 뒤집은 관계예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u2_L02_basic#5','math',6,2,'u2','L02','tb_g6_2_math_u2_L02_basic','lesson_basic','M6-2-u2-C1',2,'mc','auto','탁자 위에 컵 2개와 케이크가 놓여 있고, 가·나·다 세 방향에서 사진을 찍었어요(『수학익힘』 27쪽). 가 방향에서 찍은 사진은 어떻게 보이나요?',ARRAY['M6-2-u2-X19','M6-2-u2-X05','M6-2-u2-X15']::text[],true,'{"seq":5,"concept":"M6-2-u2-C1","difficulty":2,"kind":"mc","stem":"탁자 위에 컵 2개와 케이크가 놓여 있고, 가·나·다 세 방향에서 사진을 찍었어요(『수학익힘』 27쪽). 가 방향에서 찍은 사진은 어떻게 보이나요?","options":[{"t":"케이크가 가장 왼쪽에 보인다","correct":true},{"t":"케이크가 컵 2개 사이에 보인다","mis":"M6-2-u2-X19"},{"t":"케이크가 가장 오른쪽에 보인다","mis":"M6-2-u2-X05"},{"t":"세 방향 모두 똑같이 보인다","mis":"M6-2-u2-X15"}],"explanation":["물건을 어느 방향에서 찍었는지에 따라 컵 2개와 케이크가 놓인 차례가 달라져요.","가 방향에서 보면 케이크가 가장 왼쪽에 보여요.","찍은 방향이 바뀌면 왼쪽·오른쪽 차례도 바뀌어요."],"variant_rule":{"alt":[{"stem":"탁자 위에 컵 2개와 케이크가 놓여 있고, 가·나·다 세 방향에서 사진을 찍었어요(『수학익힘』 27쪽). 나 방향에서 찍은 사진은 어떻게 보이나요?","options":[{"t":"케이크가 컵 2개 사이에 보인다","correct":true},{"t":"케이크가 가장 왼쪽에 보인다","mis":"M6-2-u2-X19"},{"t":"케이크가 가장 오른쪽에 보인다","mis":"M6-2-u2-X05"},{"t":"세 방향 모두 똑같이 보인다","mis":"M6-2-u2-X15"}],"explanation":["물건을 어느 방향에서 찍었는지에 따라 컵 2개와 케이크가 놓인 차례가 달라져요.","나 방향에서 보면 케이크가 컵 2개 사이에 보여요.","찍은 방향이 바뀌면 왼쪽·오른쪽 차례도 바뀌어요."]},{"stem":"탁자 위에 컵 2개와 케이크가 놓여 있고, 가·나·다 세 방향에서 사진을 찍었어요(『수학익힘』 27쪽). 다 방향에서 찍은 사진은 어떻게 보이나요?","options":[{"t":"케이크가 가장 오른쪽에 보인다","correct":true},{"t":"케이크가 가장 왼쪽에 보인다","mis":"M6-2-u2-X19"},{"t":"케이크가 컵 2개 사이에 보인다","mis":"M6-2-u2-X05"},{"t":"세 방향 모두 똑같이 보인다","mis":"M6-2-u2-X15"}],"explanation":["물건을 어느 방향에서 찍었는지에 따라 컵 2개와 케이크가 놓인 차례가 달라져요.","다 방향에서 보면 케이크가 가장 오른쪽에 보여요.","찍은 방향이 바뀌면 왼쪽·오른쪽 차례도 바뀌어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u2_L02_basic#6','math',6,2,'u2','L02','tb_g6_2_math_u2_L02_basic','lesson_basic','M6-2-u2-C1',2,'mc','auto','토기를 여러 방향에서 찍은 사진 세 장을 보고 가, 나, 다 가운데 같은 토기를 찾았어요. 사진에서 알 수 있는 토기의 전체 모양으로 알맞은 것은 어느 것인가요?',ARRAY['M6-2-u2-X03','M6-2-u2-X19','M6-2-u2-X15']::text[],false,'{"seq":6,"concept":"M6-2-u2-C1","difficulty":2,"kind":"mc","stem":"토기를 여러 방향에서 찍은 사진 세 장을 보고 가, 나, 다 가운데 같은 토기를 찾았어요. 사진에서 알 수 있는 토기의 전체 모양으로 알맞은 것은 어느 것인가요?","options":[{"t":"양쪽 기둥 모양이 바퀴 모양보다 높고, 양쪽 기둥이 바퀴 안쪽에 있다","correct":true},{"t":"양쪽 기둥 모양이 바퀴 모양보다 낮다","mis":"M6-2-u2-X03"},{"t":"양쪽 기둥이 바퀴 바깥쪽에 있다","mis":"M6-2-u2-X19"},{"t":"사진 한 장만 보면 전체 모양을 알 수 있다","mis":"M6-2-u2-X15"}],"explanation":["사진 한 장에는 보이지 않는 부분이 있어요.","여러 방향에서 찍은 사진을 모으면 기둥과 바퀴의 높이와 자리를 알 수 있어요.","양쪽 기둥이 바퀴보다 높고 바퀴 안쪽에 있는 토기가 같은 토기예요(교과서 답 나)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u2_L02_basic#7','math',6,2,'u2','L02','tb_g6_2_math_u2_L02_basic','lesson_basic','M6-2-u2-C1',2,'ox','auto','같은 물체라도 보는 방향에 따라 다르게 보일 수 있어요.',ARRAY['M6-2-u2-X15']::text[],false,'{"seq":7,"concept":"M6-2-u2-C1","difficulty":2,"kind":"ox","stem":"같은 물체라도 보는 방향에 따라 다르게 보일 수 있어요.","answer":"O","reason_options":[{"t":"보는 방향에 따라 보이는 부분과 보이지 않는 부분이 달라지기 때문에","correct":true},{"t":"보는 방향이 바뀌면 물체의 모양이 바뀌기 때문에","mis":"M6-2-u2-X15"}],"mis":"M6-2-u2-X15","explanation":["해태 조각상은 가 방향에서는 얼굴이, 다 방향에서는 뒷모습이 보여요.","물체는 그대로이고 보이는 부분만 달라져요.","그래서 여러 방향에서 본 모습을 모아야 전체 모양을 알 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u2_L02_basic#8','math',6,2,'u2','L02','tb_g6_2_math_u2_L02_basic','lesson_basic','M6-2-u2-C1',2,'match','auto','해태 조각상을 가, 나, 다, 라 방향에서 찍었어요. 방향과 사진에 보이는 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":8,"concept":"M6-2-u2-C1","difficulty":2,"kind":"match","stem":"해태 조각상을 가, 나, 다, 라 방향에서 찍었어요. 방향과 사진에 보이는 모습을 알맞게 이으세요.","pairs":[{"l":"가 방향","r":"해태 얼굴의 정면(앞모습)"},{"l":"나 방향","r":"해태가 왼쪽 발을 바닥에 내려놓은 옆모습"},{"l":"다 방향","r":"해태의 뒷모습"},{"l":"라 방향","r":"해태가 오른쪽 발을 공에 올려놓은 옆모습"}],"mis":"M6-2-u2-X15","explanation":["가 방향은 정면이라 얼굴이 보이고, 다 방향은 조각상 뒤쪽이라 뒷모습이 보여요.","나 방향에서는 왼쪽 발을 바닥에 내려놓은 옆모습이 보여요.","라 방향에서는 오른쪽 발을 공에 올려놓은 옆모습이 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u2_L02_basic#9','math',6,2,'u2','L02','tb_g6_2_math_u2_L02_basic','lesson_basic','M6-2-u2-C1',2,'mc','auto','선인장 2개의 사진을 2장씩 찍었어요(가, 나, 다, 라). 가와 라는 어느 방향에서 보아도 윗부분에 튀어나온 부분이 보여요. 가와 짝이 되는 사진은 어느 것인가요?',ARRAY['M6-2-u2-X15']::text[],false,'{"seq":9,"concept":"M6-2-u2-C1","difficulty":2,"kind":"mc","stem":"선인장 2개의 사진을 2장씩 찍었어요(가, 나, 다, 라). 가와 라는 어느 방향에서 보아도 윗부분에 튀어나온 부분이 보여요. 가와 짝이 되는 사진은 어느 것인가요?","options":[{"t":"라","correct":true},{"t":"나","mis":"M6-2-u2-X15"},{"t":"다","mis":"M6-2-u2-X15"},{"t":"짝을 지을 수 없다","mis":"M6-2-u2-X15"}],"explanation":["같은 선인장을 찍은 사진끼리는 모양이 서로 어긋나지 않아요.","가와 라는 둘 다 윗부분에 튀어나온 부분이 보여요.","그래서 가와 라, 나와 다가 같은 선인장을 찍은 사진이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u2_L02_basic#10','math',6,2,'u2','L02','tb_g6_2_math_u2_L02_basic','lesson_basic','M6-2-u2-C1',3,'mc','auto','선인장 사진 나에는 튀어나온 부분이 보이지 않는데, 튀어나온 부분이 보이는 다와 같은 선인장이라고 할 수 있는 까닭은 무엇인가요?',ARRAY['M6-2-u2-X15']::text[],false,'{"seq":10,"concept":"M6-2-u2-C1","difficulty":3,"kind":"mc","stem":"선인장 사진 나에는 튀어나온 부분이 보이지 않는데, 튀어나온 부분이 보이는 다와 같은 선인장이라고 할 수 있는 까닭은 무엇인가요?","options":[{"t":"튀어나온 부분이 나 방향에서는 가려졌을 수 있고, 선인장 2개를 2장씩 찍었으니 나와 다가 짝이어서","correct":true},{"t":"튀어나온 부분이 없는 선인장은 없어서","mis":"M6-2-u2-X15"},{"t":"두 사진의 화분 모양이 같아서","mis":"M6-2-u2-X15"},{"t":"나와 다는 같은 날 찍어서","mis":"M6-2-u2-X15"}],"explanation":["한 방향에서는 튀어나온 부분이 뒤에 있어 가려질 수 있어요.","선인장 2개를 2장씩 찍었으니 가와 라가 짝이면 나와 다가 짝이에요.","보이지 않는 부분은 다른 방향에서 찍은 사진으로 생각해요(지도서 180)."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u2_L02_challenge#1','math',6,2,'u2','L02','tb_g6_2_math_u2_L02_challenge','lesson_challenge','M6-2-u2-C1',2,'mc','auto','탁자 위에 컵 2개와 케이크가 놓여 있어요. 어떤 사진에서 케이크가 컵 2개 사이에 보였어요. 가·나·다 가운데 어느 방향에서 찍은 사진인가요?',ARRAY['M6-2-u2-X19','M6-2-u2-X15']::text[],false,'{"seq":1,"concept":"M6-2-u2-C1","difficulty":2,"kind":"mc","stem":"탁자 위에 컵 2개와 케이크가 놓여 있어요. 어떤 사진에서 케이크가 컵 2개 사이에 보였어요. 가·나·다 가운데 어느 방향에서 찍은 사진인가요?","options":[{"t":"나 방향","correct":true},{"t":"가 방향","mis":"M6-2-u2-X19"},{"t":"다 방향","mis":"M6-2-u2-X19"},{"t":"알 수 없다","mis":"M6-2-u2-X15"}],"explanation":["가 방향에서 보면 케이크가 가장 왼쪽에 와요.","다 방향에서 보면 케이크가 가장 오른쪽에 와요.","케이크가 컵 2개 사이에 보이는 사진은 나 방향에서 찍었어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u2_L02_challenge#2','math',6,2,'u2','L02','tb_g6_2_math_u2_L02_challenge','lesson_challenge','M6-2-u2-C1',2,'mc','auto','건물을 여러 방향에서 찍은 사진들을 보고 같은 건물을 찾으려고 해요(『수학익힘』 27쪽). 무엇을 단서로 삼으면 좋은가요?',ARRAY['M6-2-u2-X15']::text[],false,'{"seq":2,"concept":"M6-2-u2-C1","difficulty":2,"kind":"mc","stem":"건물을 여러 방향에서 찍은 사진들을 보고 같은 건물을 찾으려고 해요(『수학익힘』 27쪽). 무엇을 단서로 삼으면 좋은가요?","options":[{"t":"건물 근처 나무의 수·자리와 창문이 놓인 줄 수 같은 물체의 위치","correct":true},{"t":"사진의 크기","mis":"M6-2-u2-X15"},{"t":"사진을 찍은 시각","mis":"M6-2-u2-X15"},{"t":"건물의 색깔만","mis":"M6-2-u2-X15"}],"explanation":["여러 방향에서 찍은 사진은 모양이 달라 보여도 물체끼리의 위치는 어긋나지 않아요.","첫 번째 사진에는 건물 근처에 나무가 1그루, 세 번째 사진에는 창문이 2개씩 4줄 보여요.","이런 물체의 위치를 견주면 같은 건물을 찾을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u2_L02_challenge#3','math',6,2,'u2','L02','tb_g6_2_math_u2_L02_challenge','lesson_challenge','M6-2-u2-C1',3,'error','auto','탁자 위 컵 2개와 케이크를 가·나·다 방향에서 찍은 사진을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-2-u2-X19','M6-2-u2-X18']::text[],false,'{"seq":3,"concept":"M6-2-u2-C1","difficulty":3,"kind":"error","stem":"탁자 위 컵 2개와 케이크를 가·나·다 방향에서 찍은 사진을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"태민 — 「다 방향에서 찍어도 케이크가 가장 왼쪽에 보여.」","correct":true,"mis_target":"M6-2-u2-X19"},{"t":"서아 — 「가 방향에서 찍으면 케이크가 가장 왼쪽에 보여.」","mis":"M6-2-u2-X18"},{"t":"지호 — 「나 방향에서 찍으면 케이크가 컵 2개 사이에 보여.」","mis":"M6-2-u2-X18"}],"explanation":["가 방향에서는 케이크가 가장 왼쪽, 나 방향에서는 컵 사이에 보여요.","다 방향에서는 케이크가 가장 오른쪽에 보여요.","태민이는 찍는 방향이 바뀌어도 차례가 그대로라고 생각했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u2_L02_challenge#4','math',6,2,'u2','L02','tb_g6_2_math_u2_L02_challenge','lesson_challenge','M6-2-u2-C1',3,'mc','auto','해태 조각상 사진 가운데 하나를 나 방향에서 찍은 사진이라고 골랐어요. 알맞은 까닭은 무엇인가요?',ARRAY['M6-2-u2-X19','M6-2-u2-X05']::text[],true,'{"seq":4,"concept":"M6-2-u2-C1","difficulty":3,"kind":"mc","stem":"해태 조각상 사진 가운데 하나를 나 방향에서 찍은 사진이라고 골랐어요. 알맞은 까닭은 무엇인가요?","options":[{"t":"해태가 왼쪽 발을 바닥에 내려놓은 옆모습이 보여서","correct":true},{"t":"해태 얼굴의 정면이 보여서","mis":"M6-2-u2-X19"},{"t":"해태의 뒷모습이 보여서","mis":"M6-2-u2-X19"},{"t":"오른쪽 발을 공에 올려놓은 옆모습이 보여서","mis":"M6-2-u2-X05"}],"explanation":["가 방향은 정면, 다 방향은 뒤쪽이에요.","나 방향에서는 해태의 왼쪽 옆모습이 보여요.","그래서 왼쪽 발을 바닥에 내려놓은 사진이 나 방향 사진이에요."],"variant_rule":{"alt":[{"stem":"해태 조각상 사진 가운데 하나를 다 방향에서 찍은 사진이라고 골랐어요. 알맞은 까닭은 무엇인가요?","options":[{"t":"해태의 뒷모습이 보여서","correct":true},{"t":"해태 얼굴의 정면이 보여서","mis":"M6-2-u2-X19"},{"t":"왼쪽 발을 바닥에 내려놓은 옆모습이 보여서","mis":"M6-2-u2-X19"},{"t":"오른쪽 발을 공에 올려놓은 옆모습이 보여서","mis":"M6-2-u2-X19"}],"explanation":["다 방향은 해태 조각상의 뒤쪽이에요.","뒤쪽에서 찍으면 해태의 뒷모습이 보여요.","그래서 뒷모습이 보이는 사진이 다 방향 사진이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u2_L02_challenge#5','math',6,2,'u2','L02','tb_g6_2_math_u2_L02_challenge','lesson_challenge','M6-2-u2-C1',3,'mc','auto','산을 그린 순달이의 그림이 여울이 귀를 그린 그림과 똑같아 보였어요(단원 도입 만화). 이 일로 알 수 있는 것은 무엇인가요?',ARRAY['M6-2-u2-X15']::text[],false,'{"seq":5,"concept":"M6-2-u2-C1","difficulty":3,"kind":"mc","stem":"산을 그린 순달이의 그림이 여울이 귀를 그린 그림과 똑같아 보였어요(단원 도입 만화). 이 일로 알 수 있는 것은 무엇인가요?","options":[{"t":"서로 다른 물체도 보는 방향에 따라 같은 모양으로 보일 수 있다","correct":true},{"t":"같은 물체는 어느 방향에서 보아도 똑같이 보인다","mis":"M6-2-u2-X15"},{"t":"그림을 그리면 늘 모양이 바뀐다","mis":"M6-2-u2-X15"},{"t":"귀와 산은 모양이 같다","mis":"M6-2-u2-X15"}],"explanation":["순달이는 저기 보이는 산을, 다른 친구는 여울이 귀만 보며 올라와 귀를 그렸어요.","보는 방향에 따라 서로 다른 물체가 비슷한 모양으로 보일 수 있어요.","그래서 한 방향에서 본 모습만으로 무엇인지 단정하면 안 돼요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u2_L02_challenge#6','math',6,2,'u2','L02','tb_g6_2_math_u2_L02_challenge','lesson_challenge','M6-2-u2-C1',3,'ox','auto','첨성대처럼 왼쪽에서 본 모양과 오른쪽에서 본 모양이 같은 물체도 있어요.',ARRAY['M6-2-u2-X15']::text[],false,'{"seq":6,"concept":"M6-2-u2-C1","difficulty":3,"kind":"ox","stem":"첨성대처럼 왼쪽에서 본 모양과 오른쪽에서 본 모양이 같은 물체도 있어요.","answer":"O","reason_options":[{"t":"물체가 왼쪽과 오른쪽이 같은 모양이면 두 방향에서 본 모양이 같을 수 있어서","correct":true},{"t":"어떤 물체든 보는 방향이 달라도 늘 똑같이 보여서","mis":"M6-2-u2-X15"}],"mis":"M6-2-u2-X15","explanation":["지도서에는 첨성대를 여러 방향에서 살펴보니 왼쪽과 오른쪽에서 본 모양이 같았다는 반응이 있어요.","물체에 따라 어떤 두 방향에서 본 모양이 같을 수 있어요.","하지만 모든 물체가 어느 방향에서나 같게 보이는 것은 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u2_L02_challenge#7','math',6,2,'u2','L02','tb_g6_2_math_u2_L02_challenge','lesson_challenge','M6-2-u2-C1',3,'mc','auto','탁자 위 물건을 가 방향에서 찍었더니 케이크가 가장 왼쪽에 보였어요. 탁자를 돌아 다 방향에서 찍으면 케이크는 어디에 보이나요?',ARRAY['M6-2-u2-X19','M6-2-u2-X05','M6-2-u2-X15']::text[],false,'{"seq":7,"concept":"M6-2-u2-C1","difficulty":3,"kind":"mc","stem":"탁자 위 물건을 가 방향에서 찍었더니 케이크가 가장 왼쪽에 보였어요. 탁자를 돌아 다 방향에서 찍으면 케이크는 어디에 보이나요?","options":[{"t":"가장 오른쪽","correct":true},{"t":"가장 왼쪽","mis":"M6-2-u2-X19"},{"t":"컵 2개 사이","mis":"M6-2-u2-X05"},{"t":"보이지 않는다","mis":"M6-2-u2-X15"}],"explanation":["가 방향과 다 방향은 서로 마주 보는 쪽이에요.","마주 보는 쪽에서 보면 왼쪽과 오른쪽 차례가 거꾸로 돼요.","그래서 다 방향에서는 케이크가 가장 오른쪽에 보여요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u2_L02_challenge#8','math',6,2,'u2','L02','tb_g6_2_math_u2_L02_challenge','lesson_challenge','M6-2-u2-C1',4,'essay','teacher','토기를 여러 방향에서 찍은 사진 세 장을 보고 가, 나, 다 가운데 같은 토기를 찾았어요. 여러 방향에서 찍은 사진으로 토기의 전체 모양을 어떻게 알 수 있는지 설명해 보세요.','{}'::text[],false,'{"seq":8,"concept":"M6-2-u2-C1","difficulty":4,"kind":"essay","stem":"토기를 여러 방향에서 찍은 사진 세 장을 보고 가, 나, 다 가운데 같은 토기를 찾았어요. 여러 방향에서 찍은 사진으로 토기의 전체 모양을 어떻게 알 수 있는지 설명해 보세요.","answer_guide":{"answer":"예: 한 방향에서 찍은 사진에는 가려져 보이지 않는 부분이 있지만, 다른 방향에서 찍은 사진에는 그 부분이 보인다. 세 사진을 모아 보면 양쪽 기둥 모양의 높이가 바퀴 모양보다 높고 양쪽 기둥이 바퀴 안쪽에 있다는 것을 알 수 있다. 그래서 이런 모양의 토기인 나를 찾을 수 있다.","scoring_points":["한 방향에서는 보이지 않는 부분이 있다고 썼는가","여러 사진을 모아 기둥과 바퀴의 높이·자리를 알 수 있다고 썼는가","그 특징으로 같은 토기를 찾는다고 썼는가"]},"explanation":["한 장의 사진에는 가려진 부분이 있어요.","여러 장을 모으면 기둥과 바퀴의 높이와 자리를 알 수 있어요.","그 특징이 같은 토기를 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u2_L02_challenge#9','math',6,2,'u2','L02','tb_g6_2_math_u2_L02_challenge','lesson_challenge','M6-2-u2-C1',4,'essay','teacher','선인장 2개의 사진을 2장씩 찍었어요. 가와 라는 윗부분에 튀어나온 부분이 보이고, 나에는 튀어나온 부분이 보이지 않으며, 다에는 나와 같은 모양으로 보이는 부분이 있어요. 같은 선인장을 찍은 사진끼리 짝 짓고 그 까닭을 써 보세요.','{}'::text[],false,'{"seq":9,"concept":"M6-2-u2-C1","difficulty":4,"kind":"essay","stem":"선인장 2개의 사진을 2장씩 찍었어요. 가와 라는 윗부분에 튀어나온 부분이 보이고, 나에는 튀어나온 부분이 보이지 않으며, 다에는 나와 같은 모양으로 보이는 부분이 있어요. 같은 선인장을 찍은 사진끼리 짝 짓고 그 까닭을 써 보세요.","answer_guide":{"answer":"예: 가와 라, 나와 다가 짝이다. 가와 라는 어느 방향에서 보아도 윗부분에 튀어나온 부분이 보이므로 같은 선인장이다. 다는 나와 같은 모양으로 보이는 부분이 있고, 나는 튀어나온 부분이 뒤에 있어 가려졌을 수 있으므로 나와 다가 같은 선인장이다.","scoring_points":["가와 라, 나와 다로 짝 지었는가","튀어나온 부분이 보이는지로 까닭을 썼는가","나에서는 튀어나온 부분이 가려졌을 수 있다고 썼는가"]},"explanation":["가와 라는 튀어나온 부분이 보이는 같은 선인장이에요.","나와 다는 같은 모양으로 보이는 부분이 있어요.","나에서는 튀어나온 부분이 가려졌을 수 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u2_L02_challenge#10','math',6,2,'u2','L02','tb_g6_2_math_u2_L02_challenge','lesson_challenge','M6-2-u2-C1',4,'essay','teacher','「사물 사진 찍기 놀이」에서 종이컵을 여러 방향에서 찍었더니 앞에서 찍은 사진과 오른쪽에서 찍은 사진이 같았어요. 왜 같은지 쓰고, 해태 조각상은 왜 방향마다 다르게 찍혔는지 견주어 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-2-u2-C1","difficulty":4,"kind":"essay","stem":"「사물 사진 찍기 놀이」에서 종이컵을 여러 방향에서 찍었더니 앞에서 찍은 사진과 오른쪽에서 찍은 사진이 같았어요. 왜 같은지 쓰고, 해태 조각상은 왜 방향마다 다르게 찍혔는지 견주어 써 보세요.","answer_guide":{"answer":"예: 종이컵은 둥근 모양이라 앞에서 보든 오른쪽에서 보든 보이는 모양이 똑같아서 두 사진이 같다. 해태 조각상은 앞쪽에 얼굴, 뒤쪽에 뒷모습이 있고 왼쪽 발과 오른쪽 발의 모습이 달라 보는 방향마다 보이는 부분이 달라지므로 사진이 다르게 찍힌다.","scoring_points":["종이컵은 둥글어 두 방향에서 본 모양이 같다고 썼는가","해태 조각상은 방향마다 보이는 부분이 다르다고 썼는가","두 물체를 견주어 설명했는가"]},"explanation":["종이컵은 어느 옆에서 보아도 모양이 같아요.","해태 조각상은 앞·뒤·왼쪽·오른쪽 모습이 달라요.","그래서 종이컵은 사진이 같고 해태는 사진이 달라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u2_L03_basic#1','math',6,2,'u2','L03','tb_g6_2_math_u2_L03_basic','lesson_basic','M6-2-u2-C2',1,'mc','auto','쌓은 모양을 위, 앞, 오른쪽, 뒤, 왼쪽 다섯 방향에서 본 모양을 그렸어요. 뒤집었을 때 같은 모양이 되는 짝은 어느 것인가요?',ARRAY['M6-2-u2-X17']::text[],true,'{"seq":1,"concept":"M6-2-u2-C2","difficulty":1,"kind":"mc","stem":"쌓은 모양을 위, 앞, 오른쪽, 뒤, 왼쪽 다섯 방향에서 본 모양을 그렸어요. 뒤집었을 때 같은 모양이 되는 짝은 어느 것인가요?","options":[{"t":"앞과 뒤","correct":true},{"t":"위와 앞","mis":"M6-2-u2-X17"},{"t":"위와 옆","mis":"M6-2-u2-X17"},{"t":"위와 뒤","mis":"M6-2-u2-X17"}],"explanation":["앞에서 본 모양을 뒤집으면 뒤에서 본 모양이 돼요.","오른쪽과 왼쪽도 뒤집으면 같은 모양이에요.","그래서 위, 앞, 옆 세 방향에서 본 모양만 알아도 돼요."],"variant_rule":{"alt":[{"stem":"쌓은 모양을 다섯 방향에서 본 모양 가운데 뒤집었을 때 같은 모양이 되는 짝을 하나 더 찾으면 어느 것인가요?","options":[{"t":"오른쪽과 왼쪽","correct":true},{"t":"위와 오른쪽","mis":"M6-2-u2-X17"},{"t":"위와 왼쪽","mis":"M6-2-u2-X17"},{"t":"앞과 위","mis":"M6-2-u2-X17"}],"explanation":["오른쪽에서 본 모양을 뒤집으면 왼쪽에서 본 모양이 돼요.","앞과 뒤도 마찬가지예요.","그래서 세 방향이면 쌓은 모양을 나타낼 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u2_L03_basic#2','math',6,2,'u2','L03','tb_g6_2_math_u2_L03_basic','lesson_basic','M6-2-u2-C2',1,'mc','auto','쌓기나무로 쌓은 모양을 앞에서 본 모양은 어느 것인가요?',ARRAY['M6-2-u2-X04','M6-2-u2-X17','M6-2-u2-X06']::text[],true,'{"seq":2,"concept":"M6-2-u2-C2","difficulty":1,"kind":"mc","stem":"쌓기나무로 쌓은 모양을 앞에서 본 모양은 어느 것인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"M6-2-u2-X04"},{"t":"㉰","mis":"M6-2-u2-X17"},{"t":"㉱","mis":"M6-2-u2-X06"}],"explanation":["앞에서 보면 왼쪽 줄부터 오른쪽 줄까지 차례로 보여요.","줄마다 가장 높은 층만큼 보여서 왼쪽부터 3층, 1층, 2층이에요.","맨 앞 자리가 낮아도 뒤가 높으면 높은 층까지 보여요."],"asset":{"type":"spv","cells":[[0,2,0],[0,2,1],[0,2,2],[1,2,0],[2,2,0],[2,2,1],[0,1,0],[1,1,0],[2,1,0],[0,0,0]],"show":["3d"],"cand":{"kind":"front","grids":[[1,1,3],[3,1,2],[2,1,3],[1,1,1]]}},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 쌓기나무로 쌓은 모양을 앞에서 본 모양은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"M6-2-u2-X04"},{"t":"㉯","mis":"M6-2-u2-X06"},{"t":"㉱","mis":"M6-2-u2-X03"}],"explanation":["앞에서 보면 왼쪽 줄부터 오른쪽 줄까지 차례로 보여요.","줄마다 가장 높은 층만큼 보여서 왼쪽부터 3층, 1층, 1층이에요.","맨 앞 자리가 낮아도 뒤가 높으면 높은 층까지 보여요."],"asset":{"type":"spv","cells":[[0,2,0],[0,2,1],[0,2,2],[1,2,0],[2,2,0],[0,1,0],[1,1,0],[0,0,0]],"show":["3d"],"cand":{"kind":"front","grids":[[1,1,3],[1,1,1],[3,1,1],[4,1,1]]}}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u2_L03_basic#3','math',6,2,'u2','L03','tb_g6_2_math_u2_L03_basic','lesson_basic','M6-2-u2-C2',1,'mc','auto','「옆에서 본 모양」은 어느 쪽에서 본 모양을 말하나요?',ARRAY['M6-2-u2-X19','M6-2-u2-X04']::text[],false,'{"seq":3,"concept":"M6-2-u2-C2","difficulty":1,"kind":"mc","stem":"「옆에서 본 모양」은 어느 쪽에서 본 모양을 말하나요?","options":[{"t":"앞에서 보는 사람을 기준으로 오른쪽에서 본 모양","correct":true},{"t":"앞에서 보는 사람을 기준으로 왼쪽에서 본 모양","mis":"M6-2-u2-X19"},{"t":"뒤에서 본 모양","mis":"M6-2-u2-X04"},{"t":"위에서 본 모양","mis":"M6-2-u2-X04"}],"explanation":["교과서에서 옆은 오른쪽에서 본 모양을 그려요.","방향의 기준은 앞에서 보는 친구예요.","그 친구의 오른쪽에 가서 본 모양이 옆에서 본 모양이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u2_L03_basic#4','math',6,2,'u2','L03','tb_g6_2_math_u2_L03_basic','lesson_basic','M6-2-u2-C2',1,'sa','auto','쌓은 모양에서 위에서 볼 때 보이는 부분에 빨간색을 칠하려고 해요. 빨간색을 칠하는 쌓기나무는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-2-u2-C2","difficulty":1,"kind":"sa","stem":"쌓은 모양에서 위에서 볼 때 보이는 부분에 빨간색을 칠하려고 해요. 빨간색을 칠하는 쌓기나무는 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["위에서 보면 자리마다 맨 위의 쌓기나무가 하나씩 보여요.","쌓기나무가 놓인 자리가 5곳이에요.","그래서 빨간색은 쌓기나무 5개에 칠해요(지도서 184)."],"asset":{"type":"spv","cells":[[1,2,0],[1,2,1],[2,2,0],[0,1,0],[1,1,0],[1,0,0]],"show":["3d"]},"variant_rule":{"alt":[{"stem":"쌓은 모양에서 앞에서 볼 때 보이는 부분에 노란색을 칠하려고 해요. 노란색을 칠하는 쌓기나무는 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["앞에서 보면 줄마다 가장 높은 층까지 보여요.","왼쪽부터 1층, 2층, 1층이니 1 + 2 + 1 = 4예요.","노란색은 쌓기나무 4개에 칠해요."],"asset":{"type":"spv","cells":[[1,2,0],[1,2,1],[2,2,0],[0,1,0],[1,1,0],[1,0,0]],"show":["3d"]}},{"stem":"쌓은 모양에서 옆에서 볼 때 보이는 부분에 파란색을 칠하려고 해요. 파란색을 칠하는 쌓기나무는 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["옆(오른쪽)에서 보면 줄마다 가장 높은 층까지 보여요.","앞줄부터 1층, 1층, 2층이니 1 + 1 + 2 = 4예요.","파란색은 쌓기나무 4개에 칠해요."],"asset":{"type":"spv","cells":[[1,2,0],[1,2,1],[2,2,0],[0,1,0],[1,1,0],[1,0,0]],"show":["3d"]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('tb_g6_2_math_u2_L03_basic#5','math',6,2,'u2','L03','tb_g6_2_math_u2_L03_basic','lesson_basic','M6-2-u2-C2',2,'mc','auto','쌓은 모양을 옆에서 본 모양은 어느 것인가요?',ARRAY['M6-2-u2-X04','M6-2-u2-X05','M6-2-u2-X06']::text[],true,'{"seq":5,"concept":"M6-2-u2-C2","difficulty":2,"kind":"mc","stem":"쌓은 모양을 옆에서 본 모양은 어느 것인가요?","options":[{"t":"㉰","correct":true},{"t":"㉮","mis":"M6-2-u2-X04"},{"t":"㉯","mis":"M6-2-u2-X05"},{"t":"㉱","mis":"M6-2-u2-X06"}],"explanation":["옆에서 본 모양은 오른쪽에서 본 모양이에요.","오른쪽에 서면 앞줄이 가장 왼쪽에 와서 왼쪽부터 1층, 1층, 2층이에요.","줄마다 가장 높은 층만큼 그려요."],"asset":{"type":"spv","cells":[[1,2,0],[1,2,1],[2,2,0],[0,1,0],[1,1,0],[1,0,0]],"show":["3d"],"cand":{"kind":"side","grids":[[1,2,1],[2,1,1],[1,1,2],[1,1,1]]}},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 쌓은 모양을 옆에서 본 모양은 어느 것인가요?","options":[{"t":"㉮","correct":true},{"t":"㉯","mis":"M6-2-u2-X04"},{"t":"㉰","mis":"M6-2-u2-X05"},{"t":"㉱","mis":"M6-2-u2-X06"}],"explanation":["옆에서 본 모양은 오른쪽에서 본 모양이에요.","오른쪽에 서면 앞줄이 가장 왼쪽에 와서 왼쪽부터 1층, 1층, 3층이에요.","줄마다 가장 높은 층만큼 그려요."],"asset":{"type":"spv","cells":[[0,2,0],[0,2,1],[0,2,2],[1,2,0],[2,2,0],[2,2,1],[0,1,0],[1,1,0],[2,1,0],[0,0,0]],"show":["3d"],"cand":{"kind":"side","grids":[[1,1,3],[3,1,2],[3,1,1],[1,1,2]]}}},{"stem":"이번에는 다른 보기예요. 쌓은 모양을 옆에서 본 모양은 어느 것인가요?","options":[{"t":"㉱","correct":true},{"t":"㉮","mis":"M6-2-u2-X05"},{"t":"㉯","mis":"M6-2-u2-X06"},{"t":"㉰","mis":"M6-2-u2-X03"}],"explanation":["옆에서 본 모양은 오른쪽에서 본 모양이에요.","오른쪽에 서면 앞줄이 가장 왼쪽에 와서 왼쪽부터 1층, 1층, 2층이에요.","줄마다 가장 높은 층만큼 그려요."],"asset":{"type":"spv","cells":[[0,2,0],[1,2,0],[2,2,0],[2,2,1],[0,1,0],[1,1,0],[0,0,0],[1,0,0],[2,0,0]],"show":["3d"],"cand":{"kind":"side","grids":[[2,1,1],[3,2,4],[2,1,2],[1,1,2]]}}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, source_kind=EXCLUDED.source_kind, is_active=true;
